TRANSITIONS = {
    "한도조회": ["서류제출"],
    "서류제출": ["심사중"],
    "심사중": ["승인", "거절"],
    "승인": ["약정"],
    "약정": ["실행완료"],
}

def can_go(src, dst):
    return dst in TRANSITIONS.get(src, [])

# 3일 뒤 돌아온 고객: 화면이 기억한 단계보다 서버의 사실이 우선
def resume(saved, server):
    if server.get("review_expired"):
        return "한도조회"          # 심사 만료 → 처음부터
    return server.get("status") or saved

print(can_go("심사중", "승인"))     # True
print(can_go("서류제출", "약정"))   # False
print(resume("서류제출", {"status": "심사중"}))                 # 심사중
print(resume("약정", {"status": "약정", "review_expired": True}))  # 한도조회
